const { add } = require('./sum.js');
const cases = [[['1','2'],3], [[1,2],3], [['10','5.5'],15.5], [[2,'3'],5], [['-1',1],0], [[0,0],0], [['100','23'],123]];
for (const [args, exp] of cases) {
  const r = add(...args);
  if (r !== exp) { console.error('fail', args, r); process.exit(1); }
}
console.log('ok');
